package script

import _ "embed"

// JSONSchemaBytes is the checked-in JSON Schema for ScriptDefinition,
// regenerated by `go run ./cmd/gen-script-schema` whenever a script
// type in this package changes. A runtime consumer (the MCP surface,
// once it stops sourcing its schema from zod-to-json-schema) can
// serve these bytes directly instead of calling GenerateJSONSchema
// itself.
//
//go:embed atomyx-script.schema.json
var JSONSchemaBytes []byte
